const paths={home:'M3 10 12 3l9 7 M5 9v12h5v-7h4v7h5V9',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',media:'M4 4h16v16H4z M4 15l5-5 6 6 3-3 2 2 M15 8h.01',studio:'M4 4h16v16H4z M10 8l6 4-6 4z',calendar:'M4 5h16v16H4z M4 10h16 M8 3v4 M16 3v4',research:'M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16 M16 16l6 6 M6 11l3-3 3 2 3-4',workflow:'M4 3h6v6H4z M14 15h6v6h-6z M7 9v9h7 M17 15V6h-7',channels:'M9 8l3-3a5 5 0 0 1 7 7l-3 3 M15 16l-3 3a5 5 0 0 1-7-7l3-3 M9 15l6-6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',upload:'M12 16V3 M7 8l5-5 5 5 M4 15v6h16v-6',download:'M12 3v13 M7 11l5 5 5-5 M4 17v4h16v-4',close:'M6 6l12 12 M6 18 18 6',trash:'M4 6h16 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',check:'M5 12l4 4L19 6',chevron:'M8 5l7 7-7 7',play:'M8 4l12 8-12 8z',pause:'M8 5v14 M16 5v14',file:'M5 2h9l5 5v15H5z M14 2v6h5 M8 13h8 M8 17h6',music:'M9 18V5l11-2v13 M9 8l11-2 M9 18c0 4-6 4-6 1 0-2 6-3 6-1 M20 16c0 4-6 4-6 1 0-2 6-3 6-1',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',external:'M14 3h7v7 M21 3 10 14 M10 3H3v18h18v-7',menu:'M4 6h16 M4 12h16 M4 18h16',info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 11v6 M12 7h.01',approve:'M12 3l8 3v6c0 4-8 9-8 9s-8-5-8-9V6z M8 12l3 3 5-6',leaf:'M20 3C7 2 2 9 5 16c7 4 15-1 15-13 M4 21l11-12',undo:'M9 4 3 10l6 6 M3 10h10a7 7 0 0 1 7 10'};
const channelFiles={'Instagram':'instagram','YouTube':'youtube','TikTok':'tiktok','Facebook':'facebook','Snapchat':'snapchat','LinkedIn':'linkedin','Pinterest':'pinterest','Threads':'threads','X':'x','Bluesky':'bluesky','Google Drive':'googledrive','Dropbox':'dropbox','SoundCloud':'soundcloud','Libsyn':'libsyn','Captivate.fm':'captivate','Amazon':'amazon','Twitch':'twitch'};
const icon=(name,extra='')=>['arrow','external'].includes(name)?'':`<svg class="icon ${extra}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
