let lastAccountCheck=0;
async function checkAccount(force=false){if(!sessionUser)throw new SignInRequired();if(!force&&Date.now()-lastAccountCheck<60000)return sessionUser;try{const user=await verifyAccount(sessionUser.id);lastAccountCheck=Date.now();return user;}catch(error){if(error instanceof SignInRequired){sessionUser=null;dirtyDraft=false;cleanup();cleanup=()=>{};window.activeDraft=null;state={media:[],drafts:[],references:[],plans:[],settings:{id:'brand',name:'My workspace',color:'#2348e8'},workflows:[]};db.lockAccount();if(dialog.open)closeDialog();await render();}throw error;}}
const dateLabel=value=>new Date(value).toLocaleDateString(undefined,{day:'numeric',month:'short'});
const route=()=>location.hash.slice(1).split('/')[0]||(PUBLIC_PAGES.includes(location.pathname.slice(1).replace(/\/$/,''))?location.pathname.slice(1).replace(/\/$/,''):location.pathname==='/workspace'?'media':'welcome');
const routeID=()=>location.hash.slice(1).split('/')[1]?.split('?')[0];
const navItems=[['media','media','Media library'],['studio','studio','Studio'],['calendar','calendar','Calendar'],['research','research','Research'],['workflows','workflow','Workflows'],['approvals','approve','Approvals'],['backups','download','Backups'],['channels','channels','Connections']];
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),5000);}
function button(label,action,style='primary',symbol='plus'){return `<button class="button ${style}" data-action="${action}">${symbol?icon(symbol):''}${label}</button>`;}
function empty(symbol,title,description,action='upload',label='Upload your first file'){return `<div class="empty" id="dropzone"><div class="empty-symbol">${icon(symbol)}</div><h2>${title}</h2><p>${description}</p>${action?button(label,action):''}</div>`;}
function heading(title,description,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function closeDialog(){dialog.close();dialog.innerHTML='';}
function modal(title,description,body,onSubmit){dialog.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="icon-button" data-action="close-dialog" aria-label="Close dialog">${icon('close')}</button></div><p>${description}</p><form>${body}<p class="form-error" role="alert"></p></form>`;dialog.querySelector('form').addEventListener('submit',async e=>{e.preventDefault();const submit=e.target.querySelector('[type=submit]');submit.disabled=true;try{await checkAccount();await onSubmit(new FormData(e.target),e.target);closeDialog();await refresh();}catch(error){dialog.querySelector('.form-error').textContent=error.message;submit.disabled=false;}});dialog.showModal();}
async function refresh(){const values=await Promise.all(['media','drafts','references','plans','workflows'].map(db.all));['media','drafts','references','plans','workflows'].forEach((key,i)=>state[key]=values[i]);state.settings=await db.get('settings','brand')||state.settings;await render();}
function shell(content){const r=route();if(PUBLIC_PAGES.includes(r)){landingShell(content);return;}app.innerHTML=`<div class="shell"><aside class="sidebar"><button class="icon-button mobile-close" data-action="menu" aria-label="Close navigation">${icon('close')}</button><a href="#welcome" class="brand" aria-label="Drop home"><img src="/wordmark.svg" alt="Drop"><span class="brand-label">CONTENT WORKSPACE</span></a><a class="workspace-home" href="/" aria-label="Back to Drop home">${icon('home')}<span>Home</span></a><div class="workspace-switch"><div class="avatar">${esc((state.settings.name||'CW').slice(0,2).toUpperCase())}</div><div><strong>${esc(state.settings.name||'My workspace')}</strong><small>Your content workspace</small></div></div><div class="nav-group">YOUR WORKSPACE</div><nav class="nav" aria-label="Main navigation">${navItems.map(([id,symbol,label])=>`<a href="#${id}" ${r===id?'aria-current="page"':''} class="${r===id?'active':''}">${icon(symbol)}${label}${id==='approvals'&&state.drafts.filter(d=>d.status==='review').length?`<span class="count">${state.drafts.filter(d=>d.status==='review').length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><a class="sidebar-create" href="#media"><span class="create-mark">+</span><span>Make your next move.<small>Open the media library</small></span></a><nav class="nav"><a href="#settings" class="${r==='settings'?'active':''}">${icon('settings')}Workspace settings</a></nav><div class="credit">Powered by <a href="https://corebridge.co.zw" target="_blank" rel="noopener noreferrer">corebridge.co.zw</a></div></div></aside><div class="main-wrap"><header class="topbar"><div class="inline"><button class="icon-button mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><a class="workspace-home-top" href="/" aria-label="Back to Drop home">${icon('home')}</a><div class="breadcrumb"><span class="crumb-square"></span> Your workspace <span>/</span> <b>${esc(navItems.find(n=>n[0]===r)?.[2]||({welcome:'Meet Drop',settings:'Settings'}[r])||'Media library')}</b></div></div><div class="top-actions"><a href="#settings" class="account-link">${esc(sessionUser?.name||'Account')}</a><a class="avatar" href="#settings" aria-label="Workspace settings">${esc((state.settings.name||'CW').slice(0,2).toUpperCase())}</a></div></header><main id="main" tabindex="-1">${r!=='media'?workspaceGuide(r):''}${content}<footer class="footer"><span>Drop / Made to be shared.</span><span><a href="https://corebridge.co.zw" target="_blank" rel="noopener noreferrer">Powered by corebridge.co.zw</a></span></footer></main></div></div><input id="upload-input" type="file" accept="video/*,image/*,audio/*" multiple hidden><input id="restore-input" type="file" accept=".zip,application/zip" hidden>`;document.querySelector('#upload-input').addEventListener('change',e=>upload(e.target.files));document.querySelector('#restore-input').addEventListener('change',e=>restoreBackup(e.target.files[0]));bindDrop();}
async function render(){const serial=++renderSerial;cleanup();cleanup=()=>{};const r=route();dirtyDraft=false;if(!PUBLIC_PAGES.includes(r)&&!sessionUser){landingShell(signInPage());return;}let content;if(PUBLIC_PAGES.includes(r))content=marketingPage(r);else if(r==='studio')content=studioPage();else if(r==='research')content=researchPage();else if(r==='calendar')content=calendarPage();else if(r==='channels')content=channelsPage();else if(r==='settings')content=settingsPage();else if(r==='approvals')content=approvalsPage();else if(r==='workflows')content=routeID()==='new'?workflowBuilderPage():workflowsPage();else if(r==='backups')content=backupsPage();else content=mediaPage();shell(content);if(r==='studio'&&routeID())await mountStudio(serial);if(r==='channels')mountTwitchConnection();}
function landingShell(content){const current=route();document.title=marketingTitle(current);app.innerHTML=`<div class="site-shell">${websiteHeader(current,sessionUser)}<main id="main" class="site-main" tabindex="-1">${content}</main>${websiteFooter()}</div><input id="upload-input" type="file" accept="video/*,image/*,audio/*" multiple hidden><input id="restore-input" type="file" accept=".zip,application/zip" hidden>`;document.querySelector('#upload-input').addEventListener('change',e=>upload(e.target.files));document.querySelector('#restore-input').addEventListener('change',e=>restoreBackup(e.target.files[0]));const section=new URLSearchParams(location.search||'').get('section');if(['how-it-works','demo','market-intelligence'].includes(section))setTimeout(()=>document.querySelector('#'+section)?.scrollIntoView?.({behavior:'smooth'}),50);}
function mediaPage(){const list=state.media.filter(m=>(filter==='all'||m.kind===filter)&&m.name.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>b.created-a.created);return `${heading('Your library','The raw material for your next good idea.',button('Upload content','upload','primary','upload'))}${workspaceGuide('media')}<div class="stats"><div class="stat"><div><small>In your library</small><strong>${state.media.length} <span style="font-size:11px;letter-spacing:0">files</span></strong></div>${icon('media')}</div><div class="stat"><div><small>Saved preparations</small><strong>${state.drafts.length}</strong></div>${icon('studio')}</div><div class="stat"><div><small>In your plan</small><strong>${state.plans.filter(p=>p.status!=='done').length}</strong></div>${icon('calendar')}</div></div><div class="toolbar"><div class="tabs" role="group" aria-label="Filter media">${[['all','All content'],['video','Videos'],['image','Images'],['audio','Audio']].map(([id,label])=>`<button class="tab ${filter===id?'active':''}" data-filter="${id}" aria-pressed="${filter===id}">${label}</button>`).join('')}</div><div class="search-wrap">${icon('research')}<input id="media-search" aria-label="Search media" placeholder="Find something in your library" value="${esc(search)}"></div></div><div id="upload-status" role="status"></div><div class="media-grid">${list.length?list.map(m=>`<article class="media-card"><div class="thumb">${m.thumbnail?`<img src="${esc(m.thumbnail)}" alt="" loading="lazy">`:icon(m.kind==='audio'?'music':'media')}<span class="duration">${m.kind==='image'?`${m.width} × ${m.height}`:formatTime(m.duration)}</span></div><div class="card-body"><h3 title="${esc(m.name)}">${esc(m.name)}</h3><div class="card-meta"><span>${esc(m.kind.toUpperCase())} · ${formatBytes(m.size)}</span><span>${dateLabel(m.created)}</span></div><div class="card-actions">${m.kind!=='audio'?`<a class="button secondary small" href="#studio/${m.id}">${icon('studio')}Prepare</a>`:`<button class="button secondary small" data-action="download-original" data-id="${m.id}">${icon('download')}Download</button>`}<div class="inline"><button class="icon-button" data-action="download-original" data-id="${m.id}" aria-label="Download original ${esc(m.name)}">${icon('download')}</button><button class="icon-button" data-action="rename" data-id="${m.id}" aria-label="Rename ${esc(m.name)}">${icon('file')}</button><button class="icon-button" data-action="delete-media" data-id="${m.id}" aria-label="Delete ${esc(m.name)}">${icon('trash')}</button></div></div></div></article>`).join(''):empty('upload',search?'No matching files':'Your library starts here',search?'Try a different search or content type.':'Drag a video, image or audio file here, or choose one from your device.')} </div><p class="footnote">Files are stored in this browser, not uploaded to a server. Up to 250 MB per file. Keep originals backed up; clearing site data removes this workspace.</p>`;}
function studioPage(){const id=routeID(),media=state.media.find(m=>m.id===id);if(!media||media.kind==='audio')return `${heading('Studio','A small set of tools to give your content a new shape.')}<div class="panel">${state.drafts.length?`<div class="panel-title"><h2>Saved drafts</h2><span class="pill">${state.drafts.length}</span></div>${state.drafts.map(d=>`<div class="list-row"><div><h3>${esc(d.title)}</h3><p>${d.ratio} · ${d.status==='review'?'Awaiting review':d.status==='approved'?'Approved':'Draft'} · ${dateLabel(d.updated)}</p></div><a class="button secondary small" href="#studio/${d.mediaId}?draft=${d.id}">Open ${icon('arrow')}</a></div>`).join('')}`:empty('studio','Make your first preparation','Choose a video or image from your library to crop, caption and brand it.','go-media','Choose from library')}</div>`;const draft=(new URLSearchParams(location.hash.split('?')[1]||'').get('draft')?state.drafts.find(d=>d.id===new URLSearchParams(location.hash.split('?')[1]).get('draft')&&d.mediaId===id):state.drafts.filter(d=>d.mediaId===id).sort((a,b)=>b.updated-a.updated)[0])||{id:uid(),mediaId:id,title:media.name.replace(/\.[^.]+$/,''),ratio:'9:16',start:0,end:Math.min(media.duration||10,60),position:.5,brand:state.settings.name,color:state.settings.color,captions:[],status:'draft'};window.activeDraft=structuredClone(draft);return `${heading('Prepare your content','A new format. Your voice. Ready for the next step.',`<div class="inline"><a class="button secondary" href="#media">Back to library</a>${button('Save draft','save-draft','primary','check')}${button('Save as new version','save-variant','secondary','plus')}</div>`)}<div class="studio-layout"><section><div class="panel"><div class="panel-title"><span class="small muted">${esc(media.name)}</span><span class="pill">${media.kind==='video'?formatTime(media.duration):'Image'}</span></div><div class="preview-stage"><canvas id="preview-canvas" aria-label="Prepared content preview"></canvas></div>${media.kind==='video'?`<div class="preview-controls"><button id="play-preview" class="icon-button" aria-label="Play or pause preview">${icon('play')}</button><input type="range" id="scrubber" aria-label="Preview position" min="0" max="${media.duration}" step=".05" value="${draft.start}"><span id="preview-time" class="small muted">${formatTime(draft.start)}</span></div>`:''}<div class="field" style="margin-top:20px"><label for="draft-title">Preparation name</label><input id="draft-title" value="${esc(draft.title)}" maxlength="160"></div><div class="notice" style="margin-bottom:0">${media.kind==='video'?'Video export runs in real time in this tab. Keep the page open while it records. The export format depends on your browser, usually WebM.':'Your prepared image exports as a PNG, with the selected crop, brand and caption.'}</div></div><div id="draft-status" class="help" role="status">${state.drafts.some(d=>d.mediaId===id)?'Loaded your saved draft. Changes need to be saved.':'New preparation. Save a draft to keep your settings.'}</div></section><aside class="panel"><h2>Make it fit.</h2><label>Format</label><div class="ratio-group">${Object.keys(RATIOS).map(r=>`<button class="ratio-option ${draft.ratio===r?'active':''}" data-ratio="${r}" aria-pressed="${draft.ratio===r}"><span class="ratio-shape ${r==='1:1'?'square':r==='16:9'?'wide':''}"></span>${r}<span class="small">${r==='9:16'?'Portrait':r==='1:1'?'Square':'Landscape'}</span></button>`).join('')}</div><div class="field" style="margin-top:18px"><label for="crop-position">Horizontal crop position</label><input id="crop-position" type="range" min="0" max="1" step=".01" value="${draft.position}"><p class="help">Move the crop to keep your subject in view.</p></div>${media.kind==='video'?`<div class="form-grid"><div class="field"><label for="trim-start">Start (seconds)</label><input id="trim-start" type="number" min="0" max="${media.duration}" step=".1" value="${draft.start}"></div><div class="field"><label for="trim-end">End (seconds)</label><input id="trim-end" type="number" min="0" max="${media.duration}" step=".1" value="${draft.end}"></div></div>`:''}<div class="section-label">YOUR BRAND</div><div class="form-grid"><div class="field"><label for="brand-text">Brand text</label><input id="brand-text" value="${esc(draft.brand)}" maxlength="35" placeholder="Optional brand name"></div><div class="field"><label for="brand-color">Accent colour</label><input type="color" id="brand-color" value="${draft.color||'#d85830'}"></div></div><div class="section-label">CAPTIONS</div><div id="caption-list"></div><button class="button secondary small" data-action="add-caption">${icon('plus')}Add caption</button><p class="help">Enter your own text. Times use seconds from the original video. Automatic transcription is not connected yet.</p><div class="form-actions" style="justify-content:stretch;flex-direction:column">${button(media.kind==='image'?'Export image':'Export video','export','primary','download')}${button('Send for review','request-review','secondary','approve')}</div></aside></div>`;}
let currentSource,currentCanvas,drawFrame,exportController;
async function mountStudio(serial){const media=state.media.find(m=>m.id===routeID());if(!media||media.kind==='audio')return;const url=URL.createObjectURL(media.blob);const source=media.kind==='video'?document.createElement('video'):new Image();source.src=url;if(media.kind==='video'){source.playsInline=true;source.preload='auto';}currentSource=source;currentCanvas=document.querySelector('#preview-canvas');let stopped=false;cleanup=()=>{stopped=true;if(drawFrame)cancelAnimationFrame(drawFrame);source.pause?.();URL.revokeObjectURL(url);currentSource=null;};const draw=()=>{if(stopped||serial!==renderSerial)return;const draft=window.activeDraft;const dims=RATIOS[draft.ratio];if(currentCanvas.width!==dims[0]){[currentCanvas.width,currentCanvas.height]=dims;}else if(currentCanvas.height!==dims[1])currentCanvas.height=dims[1];paint(currentCanvas.getContext('2d'),source,draft,source.currentTime||0);const scrub=document.querySelector('#scrubber');if(scrub){scrub.value=source.currentTime;document.querySelector('#preview-time').textContent=formatTime(source.currentTime);if(!source.paused&&source.currentTime>=Number(draft.end)){source.pause();document.querySelector('#play-preview').innerHTML=icon('play');}}drawFrame=requestAnimationFrame(draw);};source.addEventListener(media.kind==='video'?'loadeddata':'load',()=>{if(stopped)return;if(media.kind==='video')source.currentTime=Number(window.activeDraft.start);draw();},{once:true});source.addEventListener('error',()=>toast('This browser could not preview this file. Try another format.'),{once:true});document.querySelector('#play-preview')?.addEventListener('click',async()=>{if(source.paused){if(source.currentTime>=Number(window.activeDraft.end))source.currentTime=Number(window.activeDraft.start);try{await source.play();document.querySelector('#play-preview').innerHTML=icon('pause');}catch{toast('Unable to play this video.');}}else{source.pause();document.querySelector('#play-preview').innerHTML=icon('play');}});document.querySelector('#scrubber')?.addEventListener('input',e=>source.currentTime=Number(e.target.value));for(const [id,key] of [['draft-title','title'],['crop-position','position'],['trim-start','start'],['trim-end','end'],['brand-text','brand'],['brand-color','color']]){document.getElementById(id)?.addEventListener('input',e=>{window.activeDraft[key]=['position','start','end'].includes(key)?Number(e.target.value):e.target.value;markUnsaved();});}renderCaptions();}
function markUnsaved(){dirtyDraft=true;const el=document.querySelector('#draft-status');if(el)el.textContent='Unsaved changes. Save your draft before leaving.';}
function renderCaptions(){const el=document.querySelector('#caption-list');if(!el)return;el.innerHTML=window.activeDraft.captions.map((c,i)=>`<div class="caption-row"><input aria-label="Caption ${i+1} start in seconds" type="number" min="0" step=".1" value="${c.start}" data-caption="${i}" data-key="start"><input aria-label="Caption ${i+1} end in seconds" type="number" min="0" step=".1" value="${c.end}" data-caption="${i}" data-key="end"><button class="icon-button" data-action="remove-caption" data-index="${i}" aria-label="Remove caption ${i+1}">${icon('close')}</button><textarea aria-label="Caption ${i+1} text" data-caption="${i}" data-key="text" maxlength="240">${esc(c.text)}</textarea></div>`).join('');el.querySelectorAll('[data-caption]').forEach(input=>input.addEventListener('input',e=>{window.activeDraft.captions[Number(e.target.dataset.caption)][e.target.dataset.key]=e.target.dataset.key==='text'?e.target.value:Number(e.target.value);markUnsaved();}));}
function researchPage(){const refs=[...state.references].sort((a,b)=>b.created-a.created),summary=researchSummary(refs);return `${heading('Research','Find a pattern worth testing. Keep the evidence close.',button('Save a reference','add-reference','primary','plus'))}<div class="notice">Research starts with links and public metrics you enter. Automatic competitor tracking is not connected. Comparisons are observations, not proof of what caused a result.</div><div class="stats"><div class="stat"><div><small>Saved references</small><strong>${refs.length}</strong></div>${icon('research')}</div><div class="stat"><div><small>With recorded metrics</small><strong>${summary.measured}</strong></div>${icon('grid')}</div><div class="stat"><div><small>Median engagement*</small><strong>${summary.baseline===null?'—':summary.baseline.toFixed(2)+'%'}</strong></div>${icon('leaf')}</div></div><div class="two-col"><section class="panel"><div class="panel-title"><h2>Your reference shelf</h2><span class="pill">Manually sourced</span></div>${refs.length?refs.map(r=>`<article class="reference"><div class="inline"><span class="pill">${esc(r.platform)}</span><span class="small muted">Observed ${dateLabel(r.created)}</span></div><h3>${esc(r.title)}</h3><p>${esc(r.note||'No observation added yet.')}</p><div class="metric-row"><span>${esc(r.format||'Unspecified format')}</span>${engagement(r)!==null?`<span>${engagement(r).toFixed(2)}% engagement*</span>`:'<span>No complete metrics</span>'}</div><div class="inline"><a class="link-button" href="${esc(safeURL(r.url)||'#')}" target="_blank" rel="noopener noreferrer">View source ${icon('external')}</a><div class="inline"><button class="button secondary small" data-action="create-brief" data-id="${r.id}">Make a brief</button><button class="icon-button" data-action="delete-reference" data-id="${r.id}" aria-label="Delete reference">${icon('trash')}</button></div></div></article>`).join(''):empty('research','Keep your inspiration in reach','Save a competitor post, a useful example or a question your audience is asking.','add-reference','Save your first reference')}</section><aside class="panel"><h2>From evidence to an idea.</h2>${summary.ranked.length?`<div class="insight"><span class="eyebrow">HIGHEST RECORDED RATE</span><h3 style="margin-top:12px">${esc(summary.ranked[0].title)}</h3><p>${engagement(summary.ranked[0]).toFixed(2)}% based on the metrics you entered. Review the source before choosing what to test.</p><button class="link-button" data-action="create-brief" data-id="${summary.ranked[0].id}">Turn this into a brief ${icon('arrow')}</button></div>`:''}<div class="insight"><h3>Compare like with like.</h3><p>Choose similar platforms, audiences and observation periods. A bigger account is not automatically a better reference.</p></div><div class="insight"><h3>Borrow the lesson.</h3><p>Look at the opening, topic, format and clarity. Write an original brief that fits your business and audience.</p></div><div class="insight"><h3>Make it an experiment.</h3><p>Plan a post, then record the result. Research becomes useful when it changes your next decision.</p></div><p class="help">* (Recorded reactions + comments) ÷ followers × 100. These figures are manually entered and do not represent private reach, sales or retention.</p></aside></div>`;}
function calendarPage(){const plans=[...state.plans].sort((a,b)=>new Date(a.date)-new Date(b.date));return `${heading('Calendar','Give your next piece of content a place in the week.',button('Plan a post','add-plan','primary','plus'))}<div class="notice">This is a publication plan, not an automatic publishing queue. Export calendar reminders and publish your prepared files yourself until social connections are available. Times below use ${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}.</div><div class="calendar-items">${plans.length?plans.map(p=>`<article class="plan"><div><div class="calendar-day">${new Date(p.date).getDate()}</div><div class="calendar-month">${new Date(p.date).toLocaleDateString(undefined,{month:'short',year:'numeric'})}</div></div><div><h3>${esc(p.title)}</h3><p>${esc(p.channel)} · ${new Date(p.date).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'})} · ${p.status==='done'?'Marked as published manually':'Publishing reminder'}</p>${p.caption?`<p style="margin-top:8px;white-space:pre-wrap">${esc(p.caption)}</p>`:''}</div><div class="inline"><button class="button secondary small" data-action="calendar-export" data-id="${p.id}" aria-label="Export calendar reminder">${icon('download')}.ics</button><button class="icon-button" data-action="toggle-plan" data-id="${p.id}" aria-label="${p.status==='done'?'Mark as planned':'Mark as published manually'}">${icon(p.status==='done'?'undo':'check')}</button><button class="icon-button" data-action="delete-plan" data-id="${p.id}" aria-label="Delete planned post">${icon('trash')}</button></div></article>`).join(''):empty('calendar','A little planning goes a long way.','Add a post, choose its channel and save a reminder to your own calendar.','add-plan','Plan your first post')}</div>`;}
function channelsPage(){return `${heading('Connections','Every channel has a role. Every connection should be clear.')}<div class="notice">Prepare and download files from your device. Social accounts are not connected; publishing through Drop is currently unavailable.</div><div class="panel" style="margin-bottom:25px"><div class="panel-title"><div><h2>Local files</h2><p class="help" style="margin:7px 0 0">Upload from your device. Export prepared images and video.</p></div><span class="pill green">Available now</span></div><div class="inline">${button('Upload content','upload','secondary','upload')}<a class="link-button" href="#studio">Open studio ${icon('arrow')}</a></div></div><div class="channel-grid">${CHANNELS.map(channel=>`<article class="channel"><div class="channel-top"><div class="channel-logo"><img src="/assets/platforms/${channelFiles[channel]}.${['Libsyn','Captivate.fm','Google Drive'].includes(channel)?'png':'svg'}" alt="" width="24" height="24"></div><h3>${channel}</h3></div><span class="pill gray" ${channel==='Twitch'?'id="twitch-status"':''}>${channel==='Twitch'?'Checking…':'Not connected'}</span><p>${channel==='Twitch'?'Connect your Twitch account and browse your channel’s videos.':['Google Drive','Dropbox'].includes(channel)?'Import and cloud backup are currently unavailable.':['SoundCloud','Libsyn','Captivate.fm'].includes(channel)?'Audio publishing is currently unavailable.':channel==='Amazon'?'Commerce video publishing is currently unavailable.':'Direct publishing and account analytics are currently unavailable.'}</p>${channel==='Twitch'?'<div id="twitch-controls"><p class="help">Checking account access…</p></div>':`<button class="button secondary small" data-action="channel-info" data-channel="${channel}">View availability</button>`}</article>`).join('')}</div>`;}
function approvalsPage(){const drafts=state.drafts.filter(d=>d.status==='review'||d.status==='approved');return `${heading('Approvals','Pause, review and give your content the go-ahead.')}<div class="notice">Review and approve your own drafts here. Client invitations and shared reviews are currently unavailable.</div><div class="panel">${drafts.length?drafts.map(d=>`<div class="list-row"><div><h3>${esc(d.title)}</h3><p>${d.ratio} · <span class="pill ${d.status==='approved'?'green':'orange'}">${d.status==='approved'?'Approved locally':'Needs review'}</span></p></div><div class="inline"><a class="button secondary small" href="#studio/${d.mediaId}?draft=${d.id}">Review</a>${d.status==='review'?`<button class="button small" data-action="approve-draft" data-id="${d.id}">${icon('check')}Approve</button>`:''}</div></div>`).join(''):empty('approve','A second look, before it goes out.','Send a saved preparation for review from the studio.','go-studio','Open studio')}</div>`;}
function workflowsPage(){return `${heading('Workflows','Start with a source. Prepare a kit for where it goes next.',`<a class="button primary" href="#workflows/new">${icon('plus')}Build a workflow</a>`)}<div class="notice">These workflows prepare downloadable content kits from your library. Direct channel imports and automatic publishing are not connected.</div><div class="workflow-starters"><a href="#workflows/new"><span class="pill">Start here</span><h2>One file.<br>A content kit.</h2><p>Choose your source, destinations and formats.</p><span class="text-link">Build your own ${icon('arrow')}</span></a><button data-action="starter-workflow" data-ratio="9:16"><div class="starter-icons"><img src="/assets/platforms/instagram.svg" alt="Instagram"><img src="/assets/platforms/tiktok.svg" alt="TikTok"><img src="/assets/platforms/youtube.svg" alt="YouTube"></div><h3>Portrait content kit</h3><p>Prepare a vertical version for short-form channels.</p><span class="pill">Manual publication</span></button><button data-action="starter-workflow" data-ratio="1:1"><div class="starter-icons"><img src="/assets/platforms/linkedin.svg" alt="LinkedIn"><img src="/assets/platforms/facebook.svg" alt="Facebook"></div><h3>Square content kit</h3><p>Give an image or clip a square frame.</p><span class="pill">Manual publication</span></button></div><div class="panel"><div class="panel-title"><h2>Your saved workflows</h2><button class="link-button" data-action="add-workflow">Save a simple brand preset</button></div>${state.workflows.length?state.workflows.map(w=>`<div class="list-row"><div><h3>${esc(w.title)}</h3><p>${esc((w.ratios||[w.ratio]).join(' · '))} · ${w.destinations?.length?esc(w.destinations.join(', ')):'Brand preset'} · Manual preparation</p></div><div class="inline">${w.destinations?.length?`<button class="button secondary small" data-action="run-workflow" data-id="${w.id}">Export content kit</button>`:`<button class="button secondary small" data-action="apply-workflow" data-id="${w.id}">Use preset</button>`}<button class="icon-button" data-action="delete-workflow" data-id="${w.id}" aria-label="Delete workflow">${icon('trash')}</button></div></div>`).join(''):empty('workflow','Choose the route your content takes.','Start with a file, choose its formats and save a workflow you can use again.','new-workflow','Build your first workflow')}</div>`;}
function workflowBuilderPage(){const w=workflowDraft,media=state.media.filter(m=>m.kind!=='audio');return `${heading('Build a workflow','A clear route from your library to a prepared content kit.',`<a class="button secondary" href="#workflows">Back to workflows</a>`)}<div class="builder-steps">${['Choose a source','Plan the outputs','Save your workflow'].map((label,i)=>`<div class="${workflowStep===i+1?'active':''}"><span>${i+1}</span>${label}</div>`).join('')}</div><section class="panel workflow-builder">${workflowStep===1?`<span class="eyebrow">01 / START HERE</span><h2>Where is the original?</h2><div class="source-choices"><div class="source-choice active">${icon('media')}<strong>Your media library</strong><p>Use a file already saved in this browser.</p><span class="pill green">Available now</span></div><button class="source-choice" data-action="source-unavailable">${icon('channels')}<strong>A social channel</strong><p>Import new posts from a connected account.</p><span class="pill gray">Not connected yet</span></button></div><div class="field"><label for="workflow-source">Choose a starting file</label><select id="workflow-source"><option value="">Choose an image or video</option>${media.map(m=>`<option value="${m.id}" ${w.sourceId===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select>${!media.length?'<p class="help">Upload an image or video to your library first.</p><a class="text-link" href="#media">Open media library</a>':''}</div>`:workflowStep===2?`<span class="eyebrow">02 / GIVE IT A DIRECTION</span><h2>What are you preparing for?</h2><p class="help">These are preparation targets, not connected publishing accounts.</p><div class="destination-picker">${PREPARATION_CHANNELS.map(c=>`<button class="destination-option ${w.destinations.includes(c)?'active':''}" data-action="workflow-destination" data-channel="${c}" aria-pressed="${w.destinations.includes(c)}"><img src="/assets/platforms/${channelFiles[c]}.svg" alt="" width="22" height="22"><span>${c}</span>${w.destinations.includes(c)?icon('check'):icon('plus')}</button>`).join('')}</div><div class="section-label">OUTPUT FORMATS</div><div class="ratio-group">${Object.keys(RATIOS).map(r=>`<button class="ratio-option ${w.ratios.includes(r)?'active':''}" data-action="workflow-ratio" data-format="${r}" aria-pressed="${w.ratios.includes(r)}">${r}<span>${r==='9:16'?'Portrait':r==='1:1'?'Square':'Landscape'}</span></button>`).join('')}</div>`:`<span class="eyebrow">03 / READY FOR NEXT TIME</span><h2>Give this workflow a name.</h2><div class="field"><label for="workflow-title">Workflow name</label><input id="workflow-title" maxlength="100" value="${esc(w.title)}" placeholder="Weekly content kit"></div><div class="workflow-summary"><div><span>Source</span><strong>${esc(state.media.find(m=>m.id===w.sourceId)?.name||'Choose on each run')}</strong></div><div><span>Destinations</span><strong>${esc(w.destinations.join(', '))}</strong></div><div><span>Formats</span><strong>${esc(w.ratios.join(' · '))}</strong></div><div><span>Delivery</span><strong>Downloadable ZIP · Manual publication</strong></div></div><p class="help">Your current default brand will be saved with this workflow. Review the file and captions in Studio before running a kit.</p>`}<div class="form-actions">${workflowStep>1?button('Back','workflow-back','secondary',''):''}${workflowStep<3?button('Continue','workflow-next','primary','arrow'):button('Save workflow','workflow-save','primary','check')}</div></section>`;}
function backupsPage(){return `${heading('Backups','Keep a complete copy of your own work.')}<div class="two-col"><section class="panel"><span class="pill green">Available now</span><h2 style="margin-top:18px">A backup with your files inside.</h2><p class="small muted">Download one ZIP containing your original media, drafts, references, plans, brand settings and workflows.</p><p class="help">${state.media.length} media files · ${formatBytes(state.media.reduce((n,m)=>n+m.size,0))}. Browser archives are limited to 500 MB. The archive is not encrypted; keep it somewhere private.</p>${button('Download full backup','full-backup','primary','download')}</section><section class="panel"><h2>Bring a backup back.</h2><p class="small muted">Restore a ZIP created by Drop to this signed-in account. Existing records are kept; duplicates are skipped.</p>${button('Choose a Drop backup','restore-backup','secondary','upload')}<p class="help">The whole import is committed together. If validation or browser storage fails, the restore is cancelled.</p></section></div><div class="notice" style="margin-top:22px">Google Drive and Dropbox cloud backups are not connected. Downloading a ZIP does not upload it to either service.</div>`;}
function settingsPage(){const size=state.media.reduce((a,m)=>a+m.size,0);return `${heading('Workspace settings','Make this workspace feel like yours.')}<div class="account-panel panel"><div><span class="pill green">Verified sign-in</span><h2>${esc(sessionUser?.name||'Your account')}</h2><p>${esc(sessionUser?.email||'')} · Sign in with ChatGPT</p></div><div class="account-actions"><button class="button primary" data-action="check-signin">Check sign-in</button><a class="button secondary" href="/signout-with-chatgpt?return_to=%2F" target="_top">Sign out</a><p id="account-check-status" role="status" aria-live="polite"></p></div></div><div class="two-col"><section class="panel"><h2>Your default brand</h2><form id="brand-form"><div class="field"><label for="workspace-name">Workspace and brand name</label><input id="workspace-name" name="name" maxlength="35" required value="${esc(state.settings.name)}"></div><div class="field"><label for="workspace-color">Accent colour for exports</label><input id="workspace-color" name="color" type="color" value="${state.settings.color}"></div><p class="help">These defaults apply to new preparations. Existing drafts keep their own settings.</p><button class="button primary" type="submit">Save brand ${icon('check')}</button></form></section><aside class="panel"><h2>Your data, on this device.</h2><p class="small muted">${state.media.length} files · ${formatBytes(size)} of media</p><p class="help">Your files and plans are saved in this browser. They do not sync across devices. Browser storage can be cleared or evicted, so keep your original files.</p><a class="button primary" href="#backups">Full media backup and restore</a><p class="help">Includes your original files.</p><button class="button secondary" data-action="backup">${icon('download')}Export workspace notes</button><p class="help">The notes file includes drafts, references, plans and presets. It excludes media files. Download originals from the media library before clearing browser data.</p><details class="account-import"><summary>Recover an earlier workspace</summary><button class="button secondary small" data-action="import-legacy">Import earlier workspace</button><p class="help">Use this only on your own device. Existing records are kept.</p></details></aside></div>`;}
async function upload(files){await checkAccount();if(uploading)return;uploading=true;const errors=[];try{for(const file of files){const status=document.querySelector('#upload-status');if(status)status.innerHTML=`<div class="upload-progress">Preparing ${esc(file.name)}…</div>`;try{const details=await inspect(file);await db.put('media',{id:uid(),name:file.name,type:file.type,size:file.size,created:Date.now(),blob:file,...details});}catch(e){errors.push(`${file.name}: ${e.message}`);}}await refresh();toast(errors.length?errors.join(' · '):'Your files are saved in this browser.');}finally{uploading=false;}}
function bindDrop(){const zone=document.querySelector('#dropzone');if(zone){zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('drag');});zone.addEventListener('dragleave',()=>zone.classList.remove('drag'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('drag');upload(e.dataTransfer.files);});}}
function addReference(){modal('Save a reference','Keep the source and your own observation together.',`<div class="field"><label for="ref-title">Post or reference title</label><input id="ref-title" name="title" required maxlength="160" placeholder="What caught your attention?"></div><div class="field"><label for="ref-url">Source link</label><input id="ref-url" name="url" type="url" required placeholder="https://…"></div><div class="form-grid"><div class="field"><label for="ref-platform">Platform</label><select id="ref-platform" name="platform">${[...CHANNELS,'Website','Other'].map(c=>`<option>${c}</option>`).join('')}</select></div><div class="field"><label for="ref-format">Content format</label><select id="ref-format" name="format"><option>Short video</option><option>Long video</option><option>Image</option><option>Carousel</option><option>Text</option><option>Audio</option></select></div></div><div class="field"><label for="ref-note">Your observation</label><textarea id="ref-note" name="note" maxlength="2000" placeholder="What is worth learning from? What could you test?"></textarea></div><div class="form-grid"><div class="field"><label for="ref-followers">Followers (optional)</label><input id="ref-followers" name="followers" type="number" min="0" step="1"></div><div class="field"><label for="ref-reactions">Reactions (optional)</label><input id="ref-reactions" name="reactions" type="number" min="0" step="1"></div></div><div class="field"><label for="ref-comments">Comments (optional)</label><input id="ref-comments" name="comments" type="number" min="0" step="1"></div><div class="form-actions"><button class="button primary" type="submit">Save reference</button></div>`,async form=>{const data=validateReference(Object.fromEntries(form));await db.put('references',{...data,id:uid(),created:Date.now()});toast('Reference saved.');});}
function addPlan(reference){const now=new Date(Date.now()+3600000);now.setMinutes(now.getMinutes()-now.getTimezoneOffset());modal(reference?'Turn it into a brief':'Plan a post',reference?'Write your own angle, then choose where it belongs.':'Set a reminder for manual publication. This does not publish to a social account.',`<div class="field"><label for="plan-title">${reference?'Your original post idea':'Post title'}</label><input id="plan-title" name="title" required maxlength="160" value="${esc(reference?'Test: '+reference.title:'')}" placeholder="What are you sharing?"></div><div class="form-grid"><div class="field"><label for="plan-channel">Destination</label><select name="channel" id="plan-channel">${CHANNELS.map(c=>`<option ${reference?.platform===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label for="plan-date">Date and time</label><input type="datetime-local" id="plan-date" name="date" required value="${now.toISOString().slice(0,16)}"></div></div><div class="field"><label for="plan-caption">${reference?'Brief, opening and call to action':'Post description or notes'}</label><textarea id="plan-caption" name="caption" maxlength="5000" placeholder="Write the opening, key points and next step…">${esc(reference?`Observation to test: ${reference.note||'Add your observation.'}\n\nOur original angle:\n\nOpening:\n\nKey points:\n\nCall to action:\n\nSource: ${reference.url}`:'')}</textarea></div><div class="field"><label for="plan-media">Prepared content (optional)</label><select id="plan-media" name="mediaId"><option value="">Choose later</option>${state.media.map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select></div><p class="help">Timezone: ${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}. Export an .ics reminder from Calendar after saving.</p><div class="form-actions"><button class="button primary" type="submit">Save to calendar</button></div>`,async form=>{const data=Object.fromEntries(form);if(!Number.isFinite(+new Date(data.date)))throw new Error('Choose a valid date and time.');await db.put('plans',{...data,id:uid(),date:new Date(data.date).toISOString(),status:'planned',referenceId:reference?.id||null,created:Date.now()});toast('Added to your publication plan.');});}
function addWorkflow(){modal('Create a preparation preset','Save a format and brand for your next file.',`<div class="field"><label for="wf-title">Preset name</label><input id="wf-title" name="title" maxlength="100" required placeholder="Weekly portrait clips"></div><div class="field"><label for="wf-ratio">Format</label><select id="wf-ratio" name="ratio">${Object.keys(RATIOS).map(r=>`<option>${r}</option>`).join('')}</select></div><div class="field"><label for="wf-brand">Brand text</label><input id="wf-brand" name="brand" maxlength="35" value="${esc(state.settings.name)}"></div><div class="field"><label for="wf-color">Brand colour</label><input id="wf-color" type="color" name="color" value="${state.settings.color}"></div><div class="form-actions"><button class="button primary" type="submit">Save preset</button></div>`,async form=>{await db.put('workflows',{...Object.fromEntries(form),id:uid()});toast('Preset saved.');});}
async function saveDraft(status){const draft=window.activeDraft,media=state.media.find(m=>m.id===draft?.mediaId);if(!draft?.title.trim())throw new Error('Give this preparation a name.');if(media.kind==='video'&&!validateTrim(draft.start,draft.end,media.duration))throw new Error('Choose valid start and end times within the video.');for(const c of draft.captions){if(!Number.isFinite(c.start)||!Number.isFinite(c.end)||c.start<0||c.end<=c.start)throw new Error('Each caption needs an end time after its start.');if(media.kind==='video'&&c.end>media.duration+.05)throw new Error('Caption times must fit within the original video.');}const record={...draft,status:status||'draft',updated:Date.now()};await db.put('drafts',record);window.activeDraft=record;const i=state.drafts.findIndex(d=>d.id===record.id);if(i===-1)state.drafts.push(record);else state.drafts[i]=record;if(document.querySelector('#draft-status'))document.querySelector('#draft-status').textContent=`Saved ${new Date().toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'})}${status==='review'?' · Ready for review':''}.`;dirtyDraft=false;toast(status==='review'?'Added to your review checklist.':'Draft saved.');}
async function doExport(){if(exporting)return;await saveDraft();exporting=true;currentSource?.pause?.();exportController=new AbortController();const overlay=document.createElement('div');overlay.className='busy-overlay';overlay.innerHTML=`<div class="panel"><span class="eyebrow">MAKING YOUR FILE</span><h2 style="margin-top:16px">A new shape for your content.</h2><p class="help">Keep this tab open. Video exports take about as long as the selected clip.</p><progress max="100" value="0" aria-label="Export progress"></progress><p id="export-label" class="small muted">Preparing…</p><button class="button secondary" id="cancel-export">Cancel export</button></div>`;document.body.append(overlay);overlay.querySelector('#cancel-export').onclick=()=>exportController.abort();try{const media=state.media.find(m=>m.id===routeID());const {blob,extension}=await exportMedia(media,structuredClone(window.activeDraft),p=>{overlay.querySelector('progress').value=p;overlay.querySelector('#export-label').textContent=`${Math.round(p)}% · Preparing your export`;},exportController.signal);download(blob,`${window.activeDraft.title.replace(/[^a-zA-Z0-9 -]/g,'').trim()||'drop-export'}-${window.activeDraft.ratio.replace(':','x')}.${extension}`);toast('Your prepared file is ready to download.');}catch(e){toast(e.name==='AbortError'?'Export cancelled. Your draft is saved.':e.message);}finally{overlay.remove();exporting=false;}}
async function confirmRemove(title,description,fn){modal(title,description,`<div class="form-actions"><button class="button secondary" type="button" data-action="close-dialog">Keep it</button><button class="button danger" type="submit">Delete</button></div>`,fn);}
app.addEventListener('click',async e=>{const t=e.target.closest('[data-action],[data-filter],[data-ratio]');if(!t)return;try{if(t.dataset.filter){filter=t.dataset.filter;await render();return;}if(t.dataset.ratio&&!t.dataset.action){window.activeDraft.ratio=t.dataset.ratio;document.querySelectorAll('[data-ratio]').forEach(b=>{b.classList.toggle('active',b===t);b.setAttribute('aria-pressed',String(b===t));});markUnsaved();return;}const action=t.dataset.action,id=t.dataset.id;if(sessionUser&&!['phone-platform','website-menu','format-preview','watch-demo','menu','close-dialog'].includes(action))await checkAccount();if(action==='twitch-refresh'){await mountTwitchConnection();return;}if(action==='twitch-videos'){await showTwitchVideos();return;}if(action==='twitch-disconnect'){if(!confirm('Disconnect your Twitch account from Drop?'))return;const response=await fetch('/api/connections/twitch/disconnect',{method:'POST',credentials:'same-origin'});const data=await response.json();if(!response.ok)throw new Error(data.error||'Could not disconnect Twitch.');await mountTwitchConnection();toast(data.message||'Twitch disconnected.');return;}if(action==='check-signin'){const status=document.querySelector('#account-check-status');t.disabled=true;try{await checkAccount(true);status.textContent='Your sign-in is active. You are using '+sessionUser.email+'.';}catch(error){if(status)status.textContent=error.message;throw error;}finally{t.disabled=false;}return;}if(await workflowAction(action,t))return;if(action==='phone-platform'){if(!PHONE_PLATFORMS.includes(t.dataset.platform))return;const group=t.closest('.d-phone-showcase');group.querySelector('.d-phone-mount').innerHTML=iphonePreviewHTML(group.dataset.phonePhoto,group.dataset.phoneCaption,t.dataset.platform);group.querySelectorAll('[data-action="phone-platform"]').forEach(b=>b.setAttribute('aria-pressed',String(b===t)));}else if(action==='website-menu'){const links=document.querySelector('#website-links');const open=links.classList.toggle('open');t.setAttribute('aria-expanded',String(open));}else if(action==='format-preview'){const formats={'9:16':'Portrait','1:1':'Square','16:9':'Landscape'};if(!formats[t.dataset.format])return;document.querySelector('#format-preview').dataset.format=t.dataset.format;document.querySelector('#format-preview-label').textContent=formats[t.dataset.format]+' · '+t.dataset.format;document.querySelectorAll('[data-action="format-preview"]').forEach(b=>b.setAttribute('aria-pressed',String(b===t)));}else if(action==='watch-demo'){document.querySelector('#demo').scrollIntoView({behavior:'smooth'});document.querySelector('#demo-video').play().catch(()=>{});}else if(action==='try-example'){if(!sessionUser){location.href='/signin-with-chatgpt?return_to=%2Fworkspace%3Fexample%3D1';return;}location.hash='media';const response=await fetch('/assets/camera.jpg');if(!response.ok)throw new Error('Could not load the example photo.');await upload([new File([await response.blob()],'Drop example — camera.jpg',{type:'image/jpeg'})]);}else if(action==='import-legacy'){const count=await db.importLegacy();await refresh();toast(`Imported ${count} earlier records into this account.`);}else if(action==='upload')document.querySelector('#upload-input').click();else if(action==='go-media')location.hash='media';else if(action==='go-studio')location.hash='studio';else if(action==='menu')document.querySelector('.sidebar').classList.toggle('open');else if(action==='close-dialog')closeDialog();else if(action==='download-original'){const m=state.media.find(m=>m.id===id);download(m.blob,m.name);}else if(action==='rename'){const m=state.media.find(m=>m.id===id);modal('Rename your file','This changes its label in your workspace.',`<div class="field"><label for="rename">File name</label><input id="rename" name="name" value="${esc(m.name)}" required maxlength="200"></div><div class="form-actions"><button class="button primary" type="submit">Save name</button></div>`,async f=>{await db.put('media',{...m,name:f.get('name').trim()||m.name});});}else if(action==='delete-media')confirmRemove('Delete this file?','Its saved preparations will also be removed. Your original file on your device is unaffected.',async()=>{await db.remove('media',id);for(const d of state.drafts.filter(d=>d.mediaId===id))await db.remove('drafts',d.id);for(const p of state.plans.filter(p=>p.mediaId===id))await db.put('plans',{...p,mediaId:''});});else if(action==='add-reference')addReference();else if(action==='create-brief')addPlan(state.references.find(r=>r.id===id));else if(action==='add-plan')addPlan();else if(action==='delete-reference')confirmRemove('Delete this reference?','Its source link and recorded metrics will be removed from your shelf.',()=>db.remove('references',id));else if(action==='delete-plan')confirmRemove('Remove this planned post?','This removes the plan in Drop. Any reminder already exported to your calendar must be removed there separately.',()=>db.remove('plans',id));else if(action==='toggle-plan'){const p=state.plans.find(p=>p.id===id);await db.put('plans',{...p,status:p.status==='done'?'planned':'done'});await refresh();toast('Publication checklist updated. No social post was sent.');}else if(action==='calendar-export'){const p=state.plans.find(p=>p.id===id);download(new Blob([icsEvent(p)],{type:'text/calendar'}),'drop-publication-reminder.ics');}else if(action==='channel-info'){modal(t.dataset.channel,'Connection availability',`<div class="notice">Your account is not connected to this service. You can prepare a file, download it and publish through the service itself.</div><p class="help">Today you can prepare a file in Studio, download it, and publish through the platform itself.</p><div class="form-actions"><button class="button primary" type="submit">Understood</button></div>`,async()=>{});}else if(action==='add-caption'){window.activeDraft.captions.push({start:Number(window.activeDraft.start)||0,end:Number(window.activeDraft.end)||10,text:''});renderCaptions();markUnsaved();}else if(action==='remove-caption'){window.activeDraft.captions.splice(Number(t.dataset.index),1);renderCaptions();markUnsaved();}else if(action==='save-draft')await saveDraft();else if(action==='save-variant'){window.activeDraft.id=uid();window.activeDraft.title+=' / '+window.activeDraft.ratio;document.querySelector('#draft-title').value=window.activeDraft.title;await saveDraft();history.replaceState(null,'',`#studio/${window.activeDraft.mediaId}?draft=${window.activeDraft.id}`);}else if(action==='request-review')await saveDraft('review');else if(action==='approve-draft'){const d=state.drafts.find(d=>d.id===id);await db.put('drafts',{...d,status:'approved',updated:Date.now()});await refresh();toast('Marked approved in your personal workspace.');}else if(action==='export')await doExport();else if(action==='backup'){download(new Blob([JSON.stringify(await db.snapshot(),null,2)],{type:'application/json'}),'drop-workspace-notes.json');}else if(action==='add-workflow')addWorkflow();else if(action==='delete-workflow')confirmRemove('Delete this preset?','Existing preparations will keep their saved settings.',()=>db.remove('workflows',id));else if(action==='apply-workflow'){const w=state.workflows.find(w=>w.id===id);const media=state.media.filter(m=>m.kind!=='audio');if(!media.length){toast('Upload an image or video first.');return;}modal('Use this preset','Choose a file. This will replace its existing preparation settings.',`<div class="field"><label for="preset-file">File</label><select id="preset-file" name="mediaId">${media.map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select></div><div class="form-actions"><button class="button primary" type="submit">Open in studio</button></div>`,async f=>{const m=state.media.find(m=>m.id===f.get('mediaId'));const old=state.drafts.find(d=>d.mediaId===m.id);await db.put('drafts',{id:old?.id||uid(),mediaId:m.id,title:m.name,ratio:w.ratio,brand:w.brand,color:w.color,start:0,end:Math.min(m.duration||10,60),position:.5,captions:[],status:'draft',updated:Date.now()});location.hash=`studio/${m.id}?draft=${old?.id||state.drafts.find(d=>d.mediaId===m.id)?.id||''}`;});}}catch(error){toast(error.message);}});
dialog.addEventListener('click',e=>{if(e.target.closest('[data-action="close-dialog"]'))closeDialog();});
app.addEventListener('input',e=>{if(e.target.id==='media-search'){const pos=e.target.selectionStart;search=e.target.value;render().then(()=>{const input=document.querySelector('#media-search');input.focus();input.setSelectionRange(pos,pos);});}});
app.addEventListener('submit',async e=>{if(e.target.id!=='brand-form')return;e.preventDefault();try{await checkAccount();const form=new FormData(e.target);await db.put('settings',{id:'brand',name:String(form.get('name')).trim()||'My workspace',color:form.get('color')});await refresh();toast('Default brand saved.');}catch(error){toast(error.message);}});
window.addEventListener('hashchange',async e=>{if(exporting)exportController?.abort();if(dirtyDraft&&window.activeDraft){try{await saveDraft();}catch(error){history.replaceState(null,'',new URL(e.oldURL).hash);toast('Draft not saved: '+error.message);return;}}render().catch(error=>toast(error.message));});
window.addEventListener('focus',()=>{if(sessionUser&&!PUBLIC_PAGES.includes(route()))checkAccount(true).catch(error=>toast(error.message));});
window.addEventListener('beforeunload',e=>{if(exporting||dirtyDraft){e.preventDefault();e.returnValue='';}});
function signInPage(){return `<section class="signin-page"><span class="edition">YOUR WORKSPACE, YOUR ACCOUNT.</span><h1>Sign in to Drop.</h1><p>Continue with your ChatGPT account to open your personal content workspace. Drop never asks for or stores your password.</p><a class="button primary" href="/signin-with-chatgpt?return_to=%2Fworkspace" target="_top">Continue with ChatGPT</a><p class="help">Files remain in this browser, separated by signed-in account. Sign-in does not enable social publishing or cloud media sync.</p></section>`;}
(async()=>{try{const response=await fetch('/api/session',{credentials:'same-origin',cache:'no-store'});if(response.ok){const data=await response.json();sessionUser=data.user;lastAccountCheck=Date.now();if(!sessionUser?.id)throw new Error('The sign-in response did not contain a verified identity.');db.configureAccount(sessionUser.id);await db.openDB();await refresh();navigator.storage?.persist?.().catch(()=>{});if(new URLSearchParams(location.search).get('example')==='1'){history.replaceState(null,'','/workspace#media');const sample=await fetch('/assets/camera.jpg');if(sample.ok)await upload([new File([await sample.blob()],'Drop example — camera.jpg',{type:'image/jpeg'})]);}}else if(response.status===401){await render();}else throw new Error('Could not verify your sign-in. Refresh the page to try again.');}catch(error){landingShell(`<section class="signin-page"><h1>We could not open your workspace.</h1><p>${esc(error.message)}</p><a class="button primary" href="/workspace" target="_top">Try again</a></section>`);}})();
async function workflowAction(action,t){
 if(action==='new-workflow'){workflowStep=1;workflowDraft={title:'',sourceId:'',destinations:[],ratios:['9:16']};location.hash='workflows/new';return true;}
 if(action==='starter-workflow'){workflowStep=1;workflowDraft={title:t.dataset.ratio==='1:1'?'Square content kit':'Portrait content kit',sourceId:'',destinations:t.dataset.ratio==='1:1'?['LinkedIn','Facebook']:['Instagram','TikTok','YouTube'],ratios:[t.dataset.ratio]};location.hash='workflows/new';return true;}
 if(action==='workflow-next'){if(workflowStep===1&&!state.media.some(m=>m.id===workflowDraft.sourceId&&m.kind!=='audio'))throw new Error('Choose a file from your library first.');if(workflowStep===2&&(!workflowDraft.destinations.length||!workflowDraft.ratios.length))throw new Error('Choose at least one destination and output format.');workflowStep=Math.min(3,workflowStep+1);await render();return true;}
 if(action==='workflow-back'){workflowStep=Math.max(1,workflowStep-1);await render();return true;}
 if(action==='workflow-destination'){const c=t.dataset.channel;workflowDraft.destinations=workflowDraft.destinations.includes(c)?workflowDraft.destinations.filter(v=>v!==c):[...workflowDraft.destinations,c];await render();return true;}
 if(action==='workflow-ratio'){const r=t.dataset.format;workflowDraft.ratios=workflowDraft.ratios.includes(r)?workflowDraft.ratios.filter(v=>v!==r):[...workflowDraft.ratios,r];await render();return true;}
 if(action==='workflow-save'){const data=validateWorkflow({...workflowDraft,id:uid(),brand:state.settings.name,color:state.settings.color,ratio:workflowDraft.ratios[0]});await db.put('workflows',data);workflowStep=1;workflowDraft={title:'',sourceId:'',destinations:[],ratios:['9:16']};location.hash='workflows';await refresh();toast('Workflow saved. Run it to export a content kit.');return true;}
 if(action==='source-unavailable'){modal('Channel imports are not connected','Start from a file in your library today.',`<p class="help">Importing future posts requires an authorised connection to the source platform. This build does not monitor social accounts or import their posts.</p><div class="form-actions"><button class="button primary" type="submit">Use the library</button></div>`,async()=>{});return true;}
 if(action==='run-workflow'){const w=state.workflows.find(w=>w.id===t.dataset.id),files=state.media.filter(m=>m.kind!=='audio');if(!files.length)throw new Error('Upload an image or video first.');modal('Prepare a content kit','Exports your chosen formats into one ZIP. Publication remains manual.',`<div class="field"><label for="kit-file">Original file</label><select id="kit-file" name="mediaId">${files.map(m=>`<option value="${m.id}" ${m.id===w.sourceId?'selected':''}>${esc(m.name)}</option>`).join('')}</select></div><p class="help">Formats: ${esc((w.ratios||[w.ratio]).join(', '))}. Destinations: ${esc(w.destinations.join(', '))}. The latest saved preparation supplies the trim and captions; the workflow supplies branding.</p><div class="form-actions"><button class="button primary" type="submit">Export kit</button></div>`,async form=>{const media=state.media.find(m=>m.id===form.get('mediaId'));setTimeout(()=>exportKit(w,media).catch(error=>toast(error.message)),0);});return true;}
 if(action==='full-backup'){toast('Preparing your media backup…');try{const backup=await createBackup(await db.exportRecords());download(backup,'drop-workspace-backup.zip');toast('Full workspace backup is ready.');}catch(error){toast(error.message);}return true;}
 if(action==='restore-backup'){document.querySelector('#restore-input').click();return true;}
 return false;
}
app.addEventListener('change',e=>{if(e.target.id==='workflow-source')workflowDraft.sourceId=e.target.value;});
app.addEventListener('input',e=>{if(e.target.id==='workflow-title')workflowDraft.title=e.target.value;});
async function exportKit(workflow,media){if(exporting)throw new Error('An export is already running.');exporting=true;exportController=new AbortController();const overlay=document.createElement('div');overlay.className='busy-overlay';overlay.innerHTML=`<div class="panel"><span class="eyebrow">PREPARING YOUR KIT</span><h2 style="margin-top:15px">A few new forms.</h2><p class="help">Keep this tab open. Video formats are prepared one at a time, in real time.</p><progress max="100" value="0" aria-label="Content kit progress"></progress><p id="kit-status" class="help">Starting…</p><button class="button secondary" id="kit-cancel">Cancel</button></div>`;document.body.append(overlay);overlay.querySelector('#kit-cancel').onclick=()=>exportController.abort();try{const saved=state.drafts.filter(d=>d.mediaId===media.id).sort((a,b)=>b.updated-a.updated)[0];const config={start:saved?.start||0,end:saved?.end||Math.min(media.duration||10,60),position:saved?.position??.5,captions:saved?.captions||[],brand:workflow.brand,color:workflow.color};const entries=[],files=[],ratios=workflow.ratios||[workflow.ratio];for(let i=0;i<ratios.length;i++){if(exportController.signal.aborted)throw new DOMException('Cancelled','AbortError');overlay.querySelector('#kit-status').textContent=`Preparing ${ratios[i]} · ${i+1} of ${ratios.length}`;const out=await exportMedia(media,{...config,ratio:ratios[i]},p=>overlay.querySelector('progress').value=(i+p/100)/ratios.length*100,exportController.signal);const name=`drop-${ratios[i].replace(':','x')}.${out.extension}`;entries.push({name,blob:out.blob});files.push({name,ratio:ratios[i],type:out.blob.type});}entries.push({name:'content-plan.json',blob:new Blob([JSON.stringify(outputManifest(workflow,files),null,2)],{type:'application/json'})});overlay.querySelector('#kit-status').textContent='Packing your files…';download(await zip(entries),'drop-content-kit.zip');toast('Content kit downloaded. Review each file before publishing.');}catch(error){if(error.name==='AbortError')toast('Kit export cancelled.');else throw error;}finally{overlay.remove();exporting=false;}}
async function restoreBackup(file){if(!file)return;try{toast('Checking the backup…');const records=await readBackup(file);for(const media of records.media){const details=await inspect(new File([media.blob],media.name,{type:media.type}));if(details.kind!==media.kind)throw new Error('A media file does not match the backup metadata.');Object.assign(media,details);}modal('Restore this workspace backup?',`${records.media.length} media files and their workspace records will be copied into this account.`,`<p class="help">Existing records are kept. The archive is imported only if the whole restore succeeds.</p><div class="form-actions"><button class="button secondary" type="button" data-action="close-dialog">Cancel</button><button class="button primary" type="submit">Restore backup</button></div>`,async()=>{const n=await db.restoreRecords(records);toast(`Restored ${n} records. Existing records were kept.`);});}catch(error){toast(error.message);}}

async function mountTwitchConnection(){const status=document.querySelector('#twitch-status'),controls=document.querySelector('#twitch-controls');if(!status||!controls)return;try{const response=await fetch('/api/connections/twitch',{credentials:'same-origin',cache:'no-store'});const data=await response.json();if(!response.ok)throw new Error(data.error||'Could not check Twitch.');if(!status.isConnected)return;status.textContent=data.status==='connected'?'Connected':data.configured?'Not connected':'Unavailable';status.className='pill '+(data.status==='connected'?'green':'gray');if(data.status==='connected'){controls.innerHTML=`<p class="help">${esc(data.account.name)}</p><div class="connection-controls"><button class="button primary small" data-action="twitch-videos">Browse videos</button><button class="button secondary small" data-action="twitch-refresh">Check connection</button><button class="link-button" data-action="twitch-disconnect">Disconnect</button></div>`;}else if(data.configured){controls.innerHTML='<form method="post" action="/api/connections/twitch/start" target="_top"><button class="button primary small" type="submit">Connect Twitch</button></form>';}else controls.innerHTML='<p class="help">Twitch account connections are not available yet.</p>';const message=new URLSearchParams(location.search).get('connection');if(message?.startsWith('twitch-')){history.replaceState(null,'','/workspace#channels');toast({'twitch-connected':'Twitch account authorised.','twitch-cancelled':'Twitch authorisation cancelled.','twitch-invalid':'The connection request expired. Try again.','twitch-failed':'Twitch could not be connected. Try again.'}[message]||'Check your Twitch connection.');}}catch(error){status.textContent='Check failed';controls.innerHTML=`<p class="help">${esc(error.message)}</p><button class="button secondary small" data-action="twitch-refresh">Try again</button>`;}}
async function showTwitchVideos(){const response=await fetch('/api/connections/twitch/videos',{credentials:'same-origin',cache:'no-store'});const data=await response.json();if(!response.ok)throw new Error(data.error||'Twitch videos could not be loaded.');modal('Your Twitch videos','Open a video on Twitch. Upload your original recording to Drop to prepare new versions.',`<div class="twitch-video-list">${data.videos.length?data.videos.map(v=>`<article><h3>${esc(v.title)}</h3><p class="help">${esc(v.duration)}</p><a class="button secondary small" href="${esc(safeURL(v.url)||'#')}" target="_blank" rel="noopener noreferrer">Open on Twitch</a></article>`).join(''):'<p>No videos were returned for this account.</p>'}</div><div class="form-actions"><button class="button primary" type="submit">Done</button></div>`,async()=>{});}
